    Formats a fraction to the format %.5f [numerator/deniminator]
    :param numerator:
    :param denominator:
    :return: Formatted string
    """
def fraction_str(numerator: Any, denominator: Any) -> str {
    if (denominator > 0) {
        return (
            "%.5f [%.5f/%d]"
            % ((float(numerator) / denominator), numerator, denominator)
        );
    } else {
        return "No Data";
    }
}

