""" compute cross-product of args """
def cross(*args: Any) -> object {
    ans = [];
    for arg in args[0] {
        for arg2 in args[1] {
            ans.append((arg + arg2));
        }
    }
    return ans;
}

"""
    Exclude non-alphanumeric tokens from a list of tokens
    """
def only_alpha(tokens: Any) -> object {
    tokens = [
        token
        for token in tokens
        if token.isalpha()
    ];
    return tokens;
}

"""Get a value from nested dictionaries.
       Params
       ------
       * source (dict)   : (possibly) nested dictionary
       * keys (str, list): a string of nested keys seperated by "." or the
                           resulting list split from such a string
       Returns
       -------
       (Any) The final value

       Examples
       -------
       >>> org = {'ops': { 'manager': "Joe Smith"}, 'manager': "Bill Jones"}
       >>> rget(org, "manager")
       'Bill Jones'
       >>> rget(org, "ops.manager")
       'Joe Smith'
    """
def rget(source: Any, keys: Any) -> object {
    if (not keys or not source) {
        return;
    }
    if isinstance(keys, str) {
        keys = keys.split(".");
    }
    this_key = keys.pop(0);
    if len(keys) {
        return rget(source.get(this_key, {}), keys);
    } else {
        return source.get(this_key);
    }
}

"""
    Returns the object for that key from a dictionary.
    :param dictionary: A dictionary object
    :param key: Key to search for
    :return: Object that corresponds to the key in the dictionary
    """
def get_item(dictionary: Any, key: Any) -> object {
    return dictionary.get(key, None);
}

"""
    Checks the start and end coordinates of a sequence and returns -1 if the
    sequence comes from the 3' strand and 1 if it comes from the 5' strand

    start: An integer indicating sequence start location
    end: An integer indicating sequence end location
    """
def get_strand(start: Any, end: Any) -> object {
    if (start > end) {
        return -1;
    } elif (start <= end) {
        return 1;
    }
    return 0;
}

